'use strict';
// The same frontend runs locally and online. Cloud mode is confirmed by config.
let encryptedImport=null;
function cloudMode(){return chatConfig?.storage==='cloud';}
function cloudCopy(text){return cloudMode()?text.replaceAll('on this computer','in your private online vault').replaceAll('Another Aura tab','Another device').replaceAll('local server','server'):text;}
const originalVaultStatus=updateVaultStatus;updateVaultStatus=function(message){originalVaultStatus(cloudCopy(message));};
const localVaultForm=vaultFormHTML;vaultFormHTML=function(){return cloudCopy(localVaultForm());};
const localChatPage=chatPage;chatPage=function(){const html=localChatPage();return cloudMode()?html.replace('chats save encrypted on this computer','chats sync encrypted across your devices'):html;};
const localLogsPage=logsPage;logsPage=function(){let html=cloudCopy(localLogsPage());if(!cloudMode())return html;html=html.replace(/<p>Aura encrypts journal entries,[\s\S]*?<\/p>/,'<p>Your browser encrypts your journal, logs and preferences before they are stored online. Your passphrase stays in the browser. Sign in with the same ChatGPT account and unlock the vault on another device to restore your space.</p>').replace('This is one local vault, not a multi-user account system.','Each signed-in account has its own encrypted vault.').replace('<div class="actions"><button class="secondary" data-vault-export>','<div class="actions"><button class="secondary" data-import-backup>Import encrypted backup</button><button class="secondary" data-vault-export>');return html;};
function importPage(){return `<div class="vault-form"><div class="vault-icon">${catSymbol()}</div><h1>Bring your space with you.</h1><p>Your backup is decrypted in this browser, then saved encrypted to your online vault. The file and passphrase are not sent to Gemini.</p><form id="import-form"><label for="import-passphrase">Backup passphrase</label><input id="import-passphrase" type="password" autocomplete="current-password" required><p id="import-error" class="form-error" role="alert"></p><button class="primary" id="import-submit">Import & sync</button></form><p class="small">If you already have an online vault, unlock it first. Matching records are kept; new records are added.</p><a class="text-link" href="#logs">Back to logs</a></div>`;}
async function importEncryptedBackup(passphrase){if(!encryptedImport)throw Error('Choose an encrypted backup first.');const sourceSalt=from64(encryptedImport.salt),sourceKey=await deriveVaultKey(passphrase,sourceSalt);let snapshot;try{snapshot=await decryptAuraSnapshot(encryptedImport,sourceKey);}catch{throw Error('Could not unlock this backup. Check its passphrase and file.');}if(vaultKey)await flushAuraVault();const target=await auraLocalAPI('/api/vault');if(target.exists&&!vaultKey)throw Error('Unlock your online vault first, then choose the backup again.');if(target.exists&&target.vault.revision!==vaultRevision)throw Error('Another device saved newer data. Reload your online vault before importing.');if(!target.exists){vaultKey=sourceKey;vaultSalt=sourceSalt;vaultRevision=0;}const incoming=snapshot.state;for(const field of ['entries','moods','sessions','plans','chatLogs','weekly','sessionReviews']){const key=r=>field==='weekly'?r.week:r.id||r.date,rows=new Map((incoming[field]||[]).map(r=>[key(r),r]));for(const row of state[field]||[])rows.set(key(row),row);state[field]=[...rows.values()];}if(!chatMessages.length&&snapshot.chatMessages.length){chatMessages=snapshot.chatMessages;activeLogId=snapshot.activeLogId||crypto.randomUUID();}chatConsent=false;encryptedImport=null;window.auraPersist();await flushAuraVault();location.hash='logs';route();toast('Your space is synced.');}
const cloudRoute=route;route=function(){if(location.hash==='#import-backup'){$('#main').innerHTML=importPage();document.body.classList.remove('is-chat');$('#import-form').onsubmit=async e=>{e.preventDefault();const password=$('#import-passphrase').value;$('#import-submit').disabled=true;$('#import-error').textContent='';try{await importEncryptedBackup(password);}catch(error){$('#import-error').textContent=error.message;$('#import-submit').disabled=false;}finally{const input=$('#import-passphrase');if(input)input.value='';}};renderCats();}else cloudRoute();};
document.addEventListener('click',e=>{if(!e.target.closest('[data-import-backup]'))return;const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{if(file.size>1600000)throw Error('This backup is too large for online storage.');const record=JSON.parse(await file.text());if(record.version!==1||record.kdf!=='PBKDF2-SHA256'||record.iterations!==600000||typeof record.salt!=='string'||typeof record.iv!=='string'||typeof record.data!=='string')throw Error('Choose an Aura encrypted backup.');encryptedImport=record;location.hash='import-backup';}catch(error){toast(error.message);}};input.click();});
const clearImportedData=window.auraClearTransient;window.auraClearTransient=function(){clearImportedData?.();encryptedImport=null;};
// Fetch config early so storage labels are correct before any saving decision.
(async()=>{try{if(!chatConfig){const response=await fetch('/api/config');if(!response.ok)return;chatConfig=await response.json();}if(cloudMode()){updateVaultStatus(vaultStatus);if(['#logs','#settings','#chat'].includes(location.hash))route();}}catch{}})();
